    for(int&x:arr) cin>>x;
    deque<int> dq;
    bool first=true;
    for(int i=0;i<n;i++){
        if(!dq.empty()&&dq.front()==i-k) dq.pop_front();
        while(!dq.empty()&&arr[dq.back()]<=arr[i]) dq.pop_back();
        dq.push_back(i);
        if(i>=k-1){if(!first) cout<<' '; cout<<arr[dq.front()]; first=false;}
    }
    cout<<'\n';
}

